// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes view for the grids"
// Changes: The grids of the Changes view – the draft's precedence table, LL table and Empty/First/Follow/Predict
//          tables, with every cell the changes module reports carrying the project's (old) and the draft's (new)
//          value. Changed grid cells read "old→new" (∅ = empty) and their detail text announces both values, so the
//          change never depends on colour. Pure, renders through the shared table model (cellDetail, LLGrid).

import { analyzeGrammar } from './analysis'
import type { DraftChanges, LLEntry } from './changes'
import { EOF, SEP, fmtSet, ruleText, type LLAnalysis } from './grammar'
import type { Parts } from './parts'
import { precTable } from './precedence'
import { llSets } from './projectAnalysis'
import type { TableCell, TableModel } from './tableModel'

/** A cell of a Changes view grid; `change` is set when adopting the draft would change it. */
export interface ChangeCell extends TableCell {
  change: { old: string; new: string } | null
}

export interface ChangeGrid extends TableModel {
  rows: { head: string; cells: ChangeCell[] }[]
  /** Row/column symbols only the draft has. */
  added: string[]
  /** Row/column symbols only the project has (still shown, so their old values are visible). */
  removed: string[]
}

export interface ChangeGrids {
  precTable: ChangeGrid
  llTable: ChangeGrid
  /** Empty, First and Follow per nonterminal. */
  sets: ChangeGrid
  /** Rule text and Predict per rule number. */
  predict: ChangeGrid
}

const EMPTY = '∅'
const shown = (v: string) => v || EMPTY
const said = (v: string) => v || 'prázdne'

/** A changed cell: "old→new" in the grid; the detail says what kind of change and both sides' values. */
function changedCell(old: string, now: string, { conflict = false, what = 'zmenené', oldText = old, newText = now } = {}): ChangeCell {
  return {
    text: `${shown(old)}→${shown(now)}`,
    title: `${what}; v projekte ${said(oldText)}; v návrhu ${said(newText)}`,
    conflict,
    change: { old, new: now },
  }
}

function precChangeGrid(draft: Parts['precTable'], changes: DraftChanges['precTable']): ChangeGrid {
  const t = precTable({ ...draft, rules: '', input: '' })
  const terminals = [...t.columns.filter((c) => c !== EOF), ...changes.removedTerminals]
  const symbols = terminals.length ? [...terminals, EOF] : []
  const rel = new Map(t.rows.flatMap((row) => row.relations.map((r, i) => [row.terminal + SEP + t.columns[i], r as string] as const)))
  const changed = new Map(changes.cells.map((c) => [c.stack + SEP + c.input, c]))
  return {
    title: 'Precedenčná tabuľka – zmeny',
    header: ['Zásobník \\ vstup', ...symbols],
    rows: symbols.map((stack) => ({
      head: stack,
      cells: symbols.map((input): ChangeCell => {
        const c = changed.get(stack + SEP + input)
        if (c) return changedCell(c.old, c.new)
        return { text: rel.get(stack + SEP + input) ?? '', title: '', conflict: false, change: null }
      }),
    })),
    added: changes.addedTerminals,
    removed: changes.removedTerminals,
  }
}

const ruleNumbers = (entries: LLEntry[]) => entries.map((e) => e.rule).join(',')
const ruleList = (entries: LLEntry[]) => entries.map((e) => `${e.rule}: ${e.text}`).join(', ')

function llChangeGrid(a: LLAnalysis | null, changes: DraftChanges): ChangeGrid {
  const { cells, newConflicts, resolvedConflicts } = changes.llTable
  const removed = changes.sets.nonterminals.filter((n) => !n.new).map((n) => n.nonterminal)
  const added = changes.sets.nonterminals.filter((n) => !n.old).map((n) => n.nonterminal)
  const rows = [...(a?.N ?? []), ...removed]
  const extraCols = cells.map((c) => c.terminal).filter((t, i, all) => !a?.cols.includes(t) && all.indexOf(t) === i)
  const cols = [...(a?.cols ?? []), ...extraCols].sort((x, y) => Number(x === EOF) - Number(y === EOF))
  const key = (c: { nonterminal: string; terminal: string }) => c.nonterminal + SEP + c.terminal
  const changed = new Map(cells.map((c) => [key(c), c]))
  const fresh = new Set(newConflicts.map(key))
  const resolved = new Set(resolvedConflicts.map(key))
  return {
    title: 'LL tabuľka – zmeny',
    header: ['', ...cols],
    rows: rows.map((nonterminal) => ({
      head: nonterminal,
      cells: cols.map((terminal): ChangeCell => {
        const k = nonterminal + SEP + terminal
        const c = changed.get(k)
        if (c) {
          const what = fresh.has(k) ? 'nový konflikt' : resolved.has(k) ? 'vyriešený konflikt' : 'zmenené'
          return changedCell(ruleNumbers(c.old), ruleNumbers(c.new), { conflict: c.new.length > 1, what, oldText: ruleList(c.old), newText: ruleList(c.new) })
        }
        const rules = a?.table.get(nonterminal)?.get(terminal) ?? []
        return {
          text: rules.join(', '),
          title: rules.map((i) => `${i}: ${ruleText(a!.rules[i - 1])}`).join('\n'),
          conflict: rules.length > 1,
          change: null,
        }
      }),
    })),
    added,
    removed,
  }
}

/** A row of fields: unchanged ones show the draft's value, changed ones both sides' values. */
function fieldCells<K extends string>(keys: K[], now: Record<K, string>, old: Record<K, string> | null, changed: K[] | null): ChangeCell[] {
  return keys.map((k) =>
    changed?.includes(k) ? changedCell(old?.[k] ?? '', now[k]) : { text: now[k], title: '', conflict: false, change: null },
  )
}

const SET_FIELDS = ['empty', 'first', 'follow'] as const
const setTexts = (s: { empty: boolean; first: string[]; follow: string[] } | null) =>
  s ? { empty: s.empty ? '{ ε }' : '∅', first: fmtSet(s.first), follow: fmtSet(s.follow) } : { empty: '', first: '', follow: '' }
const PREDICT_FIELDS: ('text' | 'predict')[] = ['text', 'predict']
const predictTexts = (p: { text: string; predict: string[] } | null) => (p ? { text: p.text, predict: fmtSet(p.predict) } : { text: '', predict: '' })

function setGrids(a: LLAnalysis | null, changes: DraftChanges): Pick<ChangeGrids, 'sets' | 'predict'> {
  const now = a ? llSets(a) : { nonterminals: [], predict: [] }
  const { nonterminals, predict } = changes.sets
  const setRows = [
    ...now.nonterminals.map((n) => ({ head: n.nonterminal, now: setTexts(n), change: nonterminals.find((c) => c.nonterminal === n.nonterminal) })),
    ...nonterminals.filter((c) => !c.new).map((c) => ({ head: c.nonterminal, now: setTexts(null), change: c })),
  ]
  return {
    sets: {
      title: 'Množiny Empty, First, Follow – zmeny',
      header: ['Neterminál', 'Empty', 'First', 'Follow'],
      rows: setRows.map((r) => ({
        head: r.head,
        cells: fieldCells([...SET_FIELDS], r.now, r.change ? setTexts(r.change.old) : null, r.change ? r.change.changed : null),
      })),
      added: nonterminals.filter((c) => !c.old).map((c) => c.nonterminal),
      removed: nonterminals.filter((c) => !c.new).map((c) => c.nonterminal),
    },
    predict: {
      title: 'Predict – zmeny',
      header: ['#', 'Pravidlo', 'Predict'],
      // AI generated by: Claude Code / claude-opus-5-5
      // Prompt: "yes please fix it" (the LL Changes view flagged every cell whose rule was only renumbered)
      // Changes: Rows are the draft's rules (changes found by the draft's number), then the rules the draft removed.
      rows: [
        ...now.predict.map((p) => {
          const change = predict.find((c) => c.newRule === p.rule)
          return {
            head: String(p.rule),
            cells: fieldCells(PREDICT_FIELDS, predictTexts(p), change ? predictTexts(change.old) : null, change ? change.changed : null),
          }
        }),
        ...predict
          .filter((c) => c.newRule === null)
          .map((c) => ({ head: `${c.oldRule} (projekt)`, cells: fieldCells(PREDICT_FIELDS, predictTexts(null), predictTexts(c.old), c.changed) })),
      ],
      added: predict.filter((c) => !c.old && c.newRule !== null).map((c) => String(c.newRule)),
      removed: predict.filter((c) => !c.new && c.oldRule !== null).map((c) => String(c.oldRule)),
    },
  }
}

/** The Changes view grids of a draft (its parts) given its changes against the project. */
export function changeGrids(draft: Parts, changes: DraftChanges): ChangeGrids {
  const a = analyzeGrammar({ rules: draft.grammarRules, ...draft.definition }).ll
  return { precTable: precChangeGrid(draft.precTable, changes.precTable), llTable: llChangeGrid(a, changes), ...setGrids(a, changes) }
}
